//! The control plane's protobuf, as Rust.
//!
//! Generated by `build.rs` from `moqom/proto` and checked in, so that building a
//! relay needs no `protoc`. Regenerate with:
//!
//! ```sh
//! MOQOM_REGENERATE_PROTO=1 cargo build -p moqom-relay
//! ```
//!
//! Private to the crate, and deliberately: these types are the shape of one
//! internal API at one version, and a relay's public surface should not be
//! something the control plane can change by editing a `.proto`. Everything
//! outside [`crate::link`] deals in [`crate::roster`] and [`crate::policy`]
//! types instead, which is also what lets both be tested with no control plane
//! anywhere.
//!
//! The module nesting mirrors the proto packages because the generated code
//! refers to its neighbours by relative path: `moqom.relay.v1` names
//! `moqom.admin.v1` as `super::super::admin::v1`, and flattening either one
//! would break the other.

#![allow(missing_docs, dead_code, clippy::pedantic, clippy::all)]

pub mod admin {
    pub mod v1 {
        include!("generated/moqom.admin.v1.rs");
    }
}

pub mod relay {
    pub mod v1 {
        include!("generated/moqom.relay.v1.rs");
    }
}
